        frequency[c] = frequency.get(c, 0) + 1

    freq_list = [ (f,c) for c,f in frequency.items() ]
    freq_list.sort()

    min_freq_char = freq_list[0][0]
    for i in range(k-1):
        min_freq_char = min(min_freq_char,freq_list[i][1])

    result = set()
    for char,freq in freq_list:
        if char == min_freq_char:
            result.add(char)

    result = "".join(result)
    return result

