def decimal_to_hex(n):
    if n == 0:
        return "0"
    else:
        remainder_stack = []
        while n > 0:
            remainder_stack.append(n % 16)
            n //= 16
        result = ""
        for remainder in remainder_stack:
            if remainder < 10:
                result += str(remainder)
            else:
                result += chr(remainder - 10 + ord('A'))
        return result[::-1]
