def pancake_sort(nums):
  heap = []
  for num in nums:
    heapq.heappush(heap, -num)

  for n in range(len(nums)):
    if n >= 1:
      largest = heapq.heappop(heap)
      nums.insert(0, largest)
      del nums[1]
    elif n == 0:
      largest = heapq.heappop(heap)
      nums.insert(0, largest)
      del nums[1]
    heapq.heappush(heap, -largest)

  return nums

