def count_Intgral_Points(a, b, c, d):
  # The integral co-ordinates 
  # lying inside the square 
  # are represented by a pair (i, j) 
  # such that i lies in [a, b] 
  # and j lies in [c, d] 

  # Count the co-ordinates in 
  # both the axes separately 
  count1 = 1
  count2 = 1

  # Iterate for all the co-ordinates 
  for i in range(a + 1, b):
    if (a <= i and i <= b) and (c <= i and i <= d):
      count1 += 1

  for j in range(c + 1, d):
    if (a <= j and j <= b) and (c <= j and j <= d):
      count2 += 1

  return (count1 * count2)

