def check_brackets(snippet):
  opening_brackets = ['{','[','(']
  closing_brackets = ['}',']',')']
  stack = []
  for char in snippet:
    if char in opening_brackets:
      stack.append(char)
    elif char in closing_brackets:
      if len(stack) == 0:
        return False
      closing_bracket = closing_brackets.index(char)
      opening_bracket = opening_brackets.index(stack.pop())
      if opening_bracket != closing_bracket:
        return False
  return len(stack) == 0
