def convert_hex_to_decimal(hexadecimal):
    decimal = 0
    hex_length = len(hexadecimal)
    for i, char in enumerate(hexadecimal):
        if '0' <= char <= '9':
            decimal += int(char) * (16 ** (hex_length - i - 1))
        else:
            decimal += (hexadecimal.index(char) - 5 + 1) * (16 ** (hex_length - i - 1))
    return decimal
