                memo[j][i] = numbers[j][i]
            else:
                memo[j][i] = max(memo[j-1][i], memo[j][i-1]) + numbers[j][i]

    result = max(memo[0]) if n == 1 else max(memo[n-1]) if n == 2 else 0
    return result

