def No_of_Triangle(length, triangleSize):
  result = 0
  num_of_triangles = triangleSize // 3
  remaining = triangleSize % 3

  if length > triangleSize:
    result += (triangleSize // 3)
    remaining = triangleSize % 3
  elif length >= (triangleSize - remaining):
    result += num_of_triangles + (remaining - 1)
  else:
    result += num_of_triangles

  return result

