def max_sum(arr, n):
  # max arr to increase
  max_arr = [0] * n
  max_arr[0] = arr[0]

  # max arr to decrease
  max_decrease = [0] * n
  max_decrease[0] = arr[0]

  # Initialize result
  result = arr[0]

  # Compute maximum increasing subsequence.
  for i in range(1, n):
    for j in range(0, i):
      if arr[i] > arr[j] and max_arr[i] < max_arr[j] + arr[i]:
        max_arr[i] = max_arr[j] + arr[i]
    result = max(result, max_arr[i])

  # Compute maximum decreasing subsequence.
  for i in range(n - 1, -1, -1):
    for j in range(i - 1, -1, -1):
      if arr[i] > arr[j] and max_decrease[i] < max_decrease[j] + arr[i]:
        max_decrease[i] = max_decrease[j] + arr[i]
    result = max(result, max_decrease[i])

  return result

