def longestPalindromeSubsequence(S):

    # Base case:
    if len(S)==0:
        return 0
    if len(S)==1:
        return 1
    else:

        lps = 0
        s1 = S[:len(S)//2]
        s2 = S[len(S)//2+1:]

        lps = max(lps, longestPalindromeSubsequence(s1) + longestPalindromeSubsequence(s2))

