        j = len(s2)-1
        while (i < len(s1)) and (j >= 0):
            if s1[i]==s2[j]:
                lps = max(lps, 2 + longestPalindromeSubsequence(s1[i+1:j+1]))
            i+=1
            j-=1

        return lps

