def sum_gp(first_term, num_terms, common_ratio):
    # Check for 0 and 1 series
    if first_term == 0 or common_ratio == 1:
        return first_term * num_terms
    # Calculate the last term
    last_term = first_term * (common_ratio ** (num_terms - 1))
    # Sum of GP series using the formula (a * (1 - r^n)) / (1 - r)
    series_sum = first_term * (1 - last_term) / (1 - common_ratio)
    return round(series_sum)

def sum_gp(first_term, last_term, common_difference):
    if common_difference == 0:
        return (first_term + last_term) * (last_term - first_term + 1) // 2
    else:
        return (first_term * (1 - ((last_term - first_term) * common_difference) // (common_difference ** 2) - common_difference)) // (common_difference - 1)

