        product = nums[i]
        for j in range(i+1, len(nums)):
            product *= nums[j]
            if product < k:
                count += 1
    return count

def find_subsequences(nums, target):
    def product_subsequence(index, start, target, current, count):
        if start == len(nums):
            return count
        product = current * nums[start]
        if product < target:
            count += product_subsequence(index, start + 1, target, product, count)
        return product_subsequence(index, start + 1, target, current, count)

    return product_subsequence(0, 0, target, 1, 0)

import itertools as it
def no_of_subsequences(nums, k):
    return sum(sum(1 for x in r if prod(x) < k)
               for r in it.combinations(nums, r))
def prod(iterable):
    ans = 1
    for i in iterable:
        ans *= i
    return ans
